pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Setup: fund the account with 1 ether, set unlock time to past
        vm.deal(address(this), 2 ether);
        vm.prank(address(this));
        c.Put{value: 1 ether}(0); // unlockTime becomes block.timestamp (now)

        // Now unlockTime < block.timestamp is true, balance = 1 ether, MinSum = 1 ether
        vm.warp(block.timestamp + 1); // advance time so unlockTime < block.timestamp

        // Call Collect(1 ether) - should succeed in buggy (<=) but fail in reference (>=)
        bool success;
        try c.Collect(1 ether) {
            success = true;
        } catch {
            success = false;
        }

        // Reference (correct) requires acc.balance >= _am (1 ether >= 1 ether is true),
        // but reference also requires acc.balance >= _am, which is true.
        // Actually both require acc.balance >= MinSum (true) and block.timestamp > unlockTime (true).
        // The difference is in the second condition: reference has acc.balance >= _am (1 >= 1 true),
        // buggy has acc.balance <= _am (1 <= 1 true). Both conditions are true for both!
        // Wait - let's reconsider the bug description: "Change the balance subtraction condition from >= to <=".
        // Original: acc.balance>=MinSum && acc.balance>=_am
        // Mutant: acc.balance>=MinSum && acc.balance<=_am
        // If balance = 1 ether, _am = 1 ether, both are >= AND <=, so both would succeed.
        // We need a case where >= is false but <= is true: e.g., balance < _am.
        // Example: balance = 0.5 ether, _am = 1 ether.
        // Original: 0.5 >= 1 is false -> no collect.
        // Mutant: 0.5 <= 1 is true -> collect!
        // Let's set up that case:

        // Reset and set up properly
        vm.deal(address(this), 2 ether);
        vm.prank(address(this));
        c.Put{value: 0.5 ether}(0); // balance = 0.5 ether
        vm.warp(block.timestamp + 1);

        bool success2;
        try c.Collect(1 ether) {
            success2 = true;
        } catch {
            success2 = false;
        }

        // The reference (correct) should revert because acc.balance (0.5) < _am (1)
        // The buggy should succeed because acc.balance (0.5) <= _am (1)
        // So success2 is false for reference, true for buggy
        // We assert that success2 is false (the correct behavior)
        assertTrue(success2 == false);
    }
}

