    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Set up: fund address(this) with 1 ether and set unlock time in past
        vm.deal(address(this), 1 ether);
        vm.prank(address(this));
        c.Put{value: 1 ether}(0); // unlock time = block.timestamp (now)
        vm.warp(block.timestamp + 1); // ensure time > unlockTime

        // Attempt to collect exactly 1 ether
        bool succeeded;
        try c.Collect(1 ether) { succeeded = true; } catch { succeeded = false; }

        // Reference should revert (balance < MinSum? No, but condition fails: acc.balance >= _am becomes false for <=)
        // Actually reference: require(acc.balance >= _am) -> 1 ether >= 1 ether true → but also <= is not there, so reference passes? Wait check: reference uses >= for balance and _am. So with 1 ether balance and requesting 1 ether, it should succeed. Let's reconsider.
        // Mutation changes >= to <= in the combined condition: if(acc.balance>=MinSum && acc.balance>=_am) becomes if(acc.balance>=MinSum && acc.balance<=_am)
        // For balance = 1 ether, _am = 1 ether, reference: (1>=1e18 && 1>=1) true → succeeds. Bug: (1>=1e18 && 1<=1) true → also succeeds. They don't diverge here.
        // Need case where reference succeeds and bug fails or vice versa. Let's use _am > balance.
        // For _am = 2 ether, balance = 1 ether: reference: (1>=1e18 && 1>=2) false → revert. Bug: (1>=1e18 && 1<=2) true → succeeds. That diverges.
        // So set _am = 2 ether.
        vm.deal(address(this), 1 ether);
        vm.prank(address(this));
        c.Put{value: 1 ether}(0);
        vm.warp(block.timestamp + 1);
        bool succ;
        try c.Collect(2 ether) { succ = true; } catch { succ = false; }
        // Reference (correct) should revert because balance (1 ether) < _am (2 ether), so assertFalse(succ).
        // Bug should succeed because balance (1) <= _am (2) is true, so assertTrue(succ) would hold for bug but we need assertion that reference passes and bug fails? Wait we need one assertion that reference holds and bug breaks. If we assertFalse(succ), reference returns false (revert) passes, bug returns true fails. That's good.
        assertTrue(!succ, "Reference should revert, but bug succeeded");
    }
}

